            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Explore the foundations of computing, software engineering, algorithms, and artificial intelligence. Our programs prepare students for careers in technology and research." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study the language of the universe through pure and applied mathematics. From calculus to abstract algebra, our curriculum builds rigorous analytical thinking." },
            new() { Id = 3, Name = "English", Code = "ENGL", Description = "Develop critical reading, writing, and analytical skills through the study of literature, rhetoric, and composition across diverse traditions and time periods." },
            new() { Id = 4, Name = "Physics", Code = "PHYS", Description = "Investigate the fundamental laws governing matter, energy, space, and time. Our hands-on labs and theoretical courses cover classical mechanics to quantum physics." },
            new() { Id = 5, Name = "History", Code = "HIST", Description = "Examine the events, cultures, and ideas that have shaped human civilization. Our courses span ancient worlds to modern geopolitics with an emphasis on primary sources." }
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Sarah Chen", Title = "Professor", Email = "s.chen@university.edu", Bio = "Dr. Chen specializes in distributed systems and cloud computing. She has published over 40 peer-reviewed papers and previously worked as a senior engineer at Google. She received her Ph.D. from MIT.", DepartmentId = 1 },
            new() { Id = 2, Name = "Dr. James Rodriguez", Title = "Associate Professor", Email = "j.rodriguez@university.edu", Bio = "Dr. Rodriguez focuses on machine learning and computer vision. He leads the University AI Research Lab and has received multiple NSF grants for his work on autonomous systems.", DepartmentId = 1 },
            new() { Id = 3, Name = "Dr. Emily Watson", Title = "Professor", Email = "e.watson@university.edu", Bio = "Dr. Watson is a number theorist whose work on prime distribution has been recognized internationally. She is a fellow of the American Mathematical Society and author of two widely adopted textbooks.", DepartmentId = 2 },
            new() { Id = 4, Name = "Dr. Michael Park", Title = "Assistant Professor", Email = "m.park@university.edu", Bio = "Dr. Park specializes in applied mathematics and mathematical modeling. His research applies differential equations to epidemiological and climate models.", DepartmentId = 2 },
            new() { Id = 5, Name = "Dr. Angela Morrison", Title = "Professor", Email = "a.morrison@university.edu", Bio = "Dr. Morrison is a scholar of American literature with a focus on 20th-century fiction. She has authored three books and serves as editor of the Quarterly Literary Review.", DepartmentId = 3 },
            new() { Id = 6, Name = "Dr. Thomas Blake", Title = "Associate Professor", Email = "t.blake@university.edu", Bio = "Dr. Blake specializes in rhetoric and composition studies. He directs the University Writing Center and has developed innovative approaches to teaching academic writing.", DepartmentId = 3 },
            new() { Id = 7, Name = "Dr. Lisa Nakamura", Title = "Professor", Email = "l.nakamura@university.edu", Bio = "Dr. Nakamura is an experimental physicist whose research focuses on condensed matter physics. She has collaborated with CERN and leads the University's Advanced Materials Lab.", DepartmentId = 4 },
            new() { Id = 8, Name = "Dr. Robert Kim", Title = "Associate Professor", Email = "r.kim@university.edu", Bio = "Dr. Kim works in theoretical astrophysics and cosmology. His research on dark matter detection has been featured in Nature and Science.", DepartmentId = 4 },
            new() { Id = 9, Name = "Dr. Patricia Hernandez", Title = "Professor", Email = "p.hernandez@university.edu", Bio = "Dr. Hernandez is a historian of Latin America and the Atlantic World. Her award-winning book on colonial trade networks is considered a landmark in the field.", DepartmentId = 5 },
            new() { Id = 10, Name = "Dr. David O'Brien", Title = "Associate Professor", Email = "d.obrien@university.edu", Bio = "Dr. O'Brien specializes in modern European history with an emphasis on World War II and the Cold War. He is a frequent consultant for historical documentaries.", DepartmentId = 5 }
        };

        _courses = new List<Course>
        {
            // Computer Science
            new() { Id = 1, Title = "Introduction to Computer Science", Code = "CS 101", Description = "A broad introduction to computer science covering computational thinking, basic programming in Python, data representation, and an overview of major areas in the field. No prior programming experience required.", Credits = 3, Schedule = "MWF 10:00-10:50 AM", DepartmentId = 1, InstructorId = 1 },
            new() { Id = 2, Title = "Data Structures and Algorithms", Code = "CS 201", Description = "Study of fundamental data structures including arrays, linked lists, trees, hash tables, and graphs. Analysis of algorithm efficiency using Big-O notation. Prerequisite: CS 101.", Credits = 4, Schedule = "TTh 1:00-2:20 PM", DepartmentId = 1, InstructorId = 1 },
            new() { Id = 3, Title = "Introduction to Artificial Intelligence", Code = "CS 380", Description = "Explore the principles and techniques of artificial intelligence including search algorithms, knowledge representation, machine learning fundamentals, and neural networks. Prerequisite: CS 201.", Credits = 3, Schedule = "MWF 2:00-2:50 PM", DepartmentId = 1, InstructorId = 2 },
            new() { Id = 4, Title = "Software Engineering", Code = "CS 350", Description = "Principles of software development including requirements analysis, system design, testing, and project management. Students work in teams on a semester-long project. Prerequisite: CS 201.", Credits = 3, Schedule = "TTh 9:30-10:50 AM", DepartmentId = 1, InstructorId = 2 },

            // Mathematics
            new() { Id = 5, Title = "Calculus I", Code = "MATH 151", Description = "Limits, continuity, derivatives of algebraic and transcendental functions, applications of differentiation, and introduction to integration. Prerequisite: Pre-Calculus or placement exam.", Credits = 4, Schedule = "MWF 9:00-9:50 AM", DepartmentId = 2, InstructorId = 3 },
            new() { Id = 6, Title = "Linear Algebra", Code = "MATH 220", Description = "Systems of linear equations, matrices, determinants, vector spaces, linear transformations, eigenvalues and eigenvectors, with applications to science and engineering.", Credits = 3, Schedule = "TTh 11:00 AM-12:20 PM", DepartmentId = 2, InstructorId = 3 },
            new() { Id = 7, Title = "Probability and Statistics", Code = "MATH 360", Description = "Introduction to probability theory, random variables, distributions, hypothesis testing, confidence intervals, and regression analysis. Prerequisite: Calculus II.", Credits = 3, Schedule = "MWF 1:00-1:50 PM", DepartmentId = 2, InstructorId = 4 },
            new() { Id = 8, Title = "Differential Equations", Code = "MATH 310", Description = "First and second order ordinary differential equations, systems of equations, Laplace transforms, and numerical methods with applications to physics and engineering.", Credits = 3, Schedule = "TTh 2:30-3:50 PM", DepartmentId = 2, InstructorId = 4 },

            // English
            new() { Id = 9, Title = "College Composition", Code = "ENGL 101", Description = "Develop foundational skills in academic writing, critical reading, and argumentation. Students produce multiple essays exploring research-based and reflective writing.", Credits = 3, Schedule = "MWF 11:00-11:50 AM", DepartmentId = 3, InstructorId = 6 },
            new() { Id = 10, Title = "American Literature Survey", Code = "ENGL 250", Description = "A survey of American literature from the colonial period to the present, covering major authors, movements, and themes that have shaped the national literary identity.", Credits = 3, Schedule = "TTh 10:00-11:20 AM", DepartmentId = 3, InstructorId = 5 },
            new() { Id = 11, Title = "Creative Writing Workshop", Code = "ENGL 310", Description = "An intensive workshop in fiction and poetry writing. Students produce original work, participate in peer critique sessions, and study published examples of craft.", Credits = 3, Schedule = "W 6:00-8:50 PM", DepartmentId = 3, InstructorId = 5 },

            // Physics
            new() { Id = 12, Title = "General Physics I", Code = "PHYS 201", Description = "Mechanics, wave motion, sound, and thermodynamics with calculus-based problem solving and laboratory experiments. Co-requisite: Calculus I.", Credits = 4, Schedule = "MWF 10:00-10:50 AM, Lab F 1:00-3:50 PM", DepartmentId = 4, InstructorId = 7 },
            new() { Id = 13, Title = "General Physics II", Code = "PHYS 202", Description = "Electricity, magnetism, optics, and introduction to modern physics with calculus-based problem solving and laboratory experiments. Prerequisite: PHYS 201.", Credits = 4, Schedule = "MWF 11:00-11:50 AM, Lab Th 1:00-3:50 PM", DepartmentId = 4, InstructorId = 7 },
            new() { Id = 14, Title = "Introduction to Quantum Mechanics", Code = "PHYS 401", Description = "Wave-particle duality, Schrödinger equation, quantum states, angular momentum, spin, and applications to atomic and molecular systems. Prerequisites: PHYS 202, MATH 310.", Credits = 3, Schedule = "TTh 9:30-10:50 AM", DepartmentId = 4, InstructorId = 8 },
            new() { Id = 15, Title = "Astrophysics", Code = "PHYS 350", Description = "Stellar structure and evolution, white dwarfs, neutron stars, black holes, galaxies, and cosmology. Prerequisite: PHYS 202.", Credits = 3, Schedule = "MWF 3:00-3:50 PM", DepartmentId = 4, InstructorId = 8 },

            // History
            new() { Id = 16, Title = "World History to 1500", Code = "HIST 101", Description = "A global survey of human civilizations from prehistory through the late medieval period, examining the political, social, and cultural developments across Africa, Asia, Europe, and the Americas.", Credits = 3, Schedule = "MWF 9:00-9:50 AM", DepartmentId = 5, InstructorId = 9 },
            new() { Id = 17, Title = "Modern European History", Code = "HIST 220", Description = "Europe from the French Revolution to the present, covering industrialization, nationalism, imperialism, the World Wars, the Cold War, and European integration.", Credits = 3, Schedule = "TTh 1:00-2:20 PM", DepartmentId = 5, InstructorId = 10 },
            new() { Id = 18, Title = "The Atlantic World", Code = "HIST 330", Description = "Exploration, colonization, trade, and cultural exchange across the Atlantic from the 15th to the 19th century, with emphasis on the interactions between Europe, Africa, and the Americas.", Credits = 3, Schedule = "TTh 3:30-4:50 PM", DepartmentId = 5, InstructorId = 9 },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(int? departmentId = null, string? searchTerm = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public Instructor? GetInstructor(int id) => _instructors.FirstOrDefault(i => i.Id == id);

    public void SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        request.Id = _nextEnrollmentId++;
        request.SubmittedAt = DateTime.UtcNow;
        _enrollmentRequests.Add(request);
    }

    public List<Course> GetFeaturedCourses()
    {
        var featuredIds = new[] { 1, 3, 5, 12, 16 };
        return _courses.Where(c => featuredIds.Contains(c.Id)).ToList();
    }
}

