@page "/enroll"
@rendermode InteractiveServer
@inject ICatalogService CatalogService
@inject NavigationManager Navigation

<PageTitle>Enrollment Request</PageTitle>

<div class="container">
    <h1 class="mb-4">Enrollment Request</h1>

    @if (submitted)
    {
        <div class="alert alert-success">
            <h4 class="alert-heading">Enrollment Request Submitted!</h4>
            <p>Thank you, <strong>@enrollmentRequest.StudentName</strong>. Your request to enroll in
               <strong>@(selectedCourseName)</strong> has been received.</p>
            <hr />
            <a href="courses" class="btn btn-outline-success">Browse More Courses</a>
        </div>
    }
    else
    {
        <div class="row">
            <div class="col-lg-8">
                <EditForm Model="enrollmentRequest" OnValidSubmit="HandleSubmit" FormName="enrollForm">
                    <DataAnnotationsValidator />
                    <ValidationSummary class="text-danger mb-3" />

                    <div class="mb-3">
                        <label for="studentName" class="form-label">Student Name</label>
                        <InputText id="studentName" class="form-control" @bind-Value="enrollmentRequest.StudentName" />
                        <ValidationMessage For="@(() => enrollmentRequest.StudentName)" />
                    </div>

                    <div class="mb-3">
                        <label for="studentId" class="form-label">Student ID</label>
                        <InputText id="studentId" class="form-control" @bind-Value="enrollmentRequest.StudentId" />
                        <ValidationMessage For="@(() => enrollmentRequest.StudentId)" />
                    </div>

                    <div class="mb-3">
                        <label for="courseId" class="form-label">Course</label>
                        <InputSelect id="courseId" class="form-select" @bind-Value="enrollmentRequest.CourseId">
                            <option value="0">— Select a course —</option>
                            @foreach (var course in courses)
                            {
                                <option value="@course.Id">@course.Code — @course.Title</option>
                            }
                        </InputSelect>
                        <ValidationMessage For="@(() => enrollmentRequest.CourseId)" />
                    </div>

                    <div class="mb-3">
                        <label for="notes" class="form-label">Notes (optional)</label>
                        <InputTextArea id="notes" class="form-control" rows="3" @bind-Value="enrollmentRequest.Notes" />
                        <ValidationMessage For="@(() => enrollmentRequest.Notes)" />
                    </div>

                    <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
                </EditForm>
            </div>
        </div>
    }
</div>

@code {
    private EnrollmentRequest enrollmentRequest = new();
    private List<Course> courses = new();
    private bool submitted;
    private string selectedCourseName = string.Empty;

    protected override void OnInitialized()
    {
        courses = CatalogService.GetCourses();

        var uri = Navigation.ToAbsoluteUri(Navigation.Uri);
        if (Microsoft.AspNetCore.WebUtilities.QueryHelpers.ParseQuery(uri.Query).TryGetValue("courseId", out var courseVal)
            && int.TryParse(courseVal, out var courseId))
        {
            enrollmentRequest.CourseId = courseId;
        }
    }

    private void HandleSubmit()
    {
        var course = CatalogService.GetCourse(enrollmentRequest.CourseId);
        selectedCourseName = course is not null ? $"{course.Code} — {course.Title}" : "Unknown";
        CatalogService.SubmitEnrollmentRequest(enrollmentRequest);
        submitted = true;
    }
}

